Some rows and columns of skill 2 agree at 0.5 to 0.7 against a 0.19 median, which suggests groups of a and groups of b. I cluster them on the logits and print the block table with its purity.
```python
from scipy.cluster.hierarchy import linkage,fcluster
def silu(x): return x/(1+np.exp(-x))
def fwd(P,skill):
    a,b=np.meshgrid(np.arange(32),np.arange(32),indexing='ij')
    X=np.zeros((1024,68));X[np.arange(1024),a.ravel()]=1;X[np.arange(1024),32+b.ravel()]=1;X[:,64+skill]=1
    h=silu(X@P["l1.weight"].T+P["l1.bias"]);h2=silu(h@P["l2.weight"].T+P["l2.bias"])
    return (h2@P["l3.weight"].T+P["l3.bias"]).reshape(32,32,63)[:,:,:8]
P={n:load(n) for n in NAMES}
L=fwd(P,2);L=L-L.mean(2,keepdims=True);p=L.argmax(2)
Ro=L.reshape(32,-1);Co=L.transpose(1,0,2).reshape(32,-1)
def cl(X,n):
    return fcluster(linkage(X,'average',metric='correlation'),n,'maxclust')-1
for n in [8]:
    r=cl(Ro,n);c=cl(Co,n)
    print("row groups",[np.where(r==i)[0].tolist() for i in range(n)])
    print("col groups",[np.where(c==i)[0].tolist() for i in range(n)])
    ro=np.argsort(r);co=np.argsort(c)
    T=np.zeros((n,n),int);Pu=np.zeros((n,n))
    for i in range(n):
        for j in range(n):
            x=p[np.ix_(r==i,c==j)].ravel()
            if len(x): T[i,j]=np.bincount(x,minlength=8).argmax();Pu[i,j]=(x==T[i,j]).mean()
    print(T);print(Pu.round(2));print("purity overall",np.mean([(p[i,j]==T[r[i],c[j]]) for i in range(32) for j in range(32)]).round(3))
    for i in ro: print(r[i]," ".join(str(p[i,j]) for j in co))
    print("cols",c[co].tolist())
# correlation between logit rows: distribution
C=np.corrcoef(Ro);np.fill_diagonal(C,0);print("row corr sorted top",np.sort(C.ravel())[-12:].round(2),"median",np.median(C).round(2))
# same stats on the other three skills for reference
for s in [0,1,3]:
    Ls=fwd(P,s);Ls=Ls-Ls.mean(2,keepdims=True);Cs=np.corrcoef(Ls.reshape(32,-1));np.fill_diagonal(Cs,0);print(s,"row corr top",np.sort(Cs.ravel())[-4:].round(2),"median",np.median(Cs).round(2))
